import{_ as e,o as a,c as i,ag as o}from"./chunks/framework.CxkNbRKf.js";const s="/nada-documentation/images/indicators-codelist-list.png",n="/nada-documentation/images/indicators-codelist-detail.png",r="/nada-documentation/images/indicators-codelist-items.png",d="/nada-documentation/images/indicators-dsd-list.png",c="/nada-documentation/images/indicators-dsd-detail.png",l="/nada-documentation/images/indicators-dsd-component.png",h="/nada-documentation/images/indicators-project-overview.png",p="/nada-documentation/images/indicators-project-metadata.png",g="/nada-documentation/images/indicators-project-data.png",w=JSON.parse('{"title":"Indicators — Admin UI (codelists, DSDs, projects)","description":"","frontmatter":{},"headers":[],"relativePath":"admin-guide/content/indicators-admin.md","filePath":"admin-guide/content/indicators-admin.md","lastUpdated":1786379412000}'),m={name:"admin-guide/content/indicators-admin.md"};function u(f,t,D,b,v,S){return a(),i("div",null,[...t[0]||(t[0]=[o('<h1 id="indicators-—-admin-ui-codelists-dsds-projects" tabindex="-1">Indicators — Admin UI (codelists, DSDs, projects) <a class="header-anchor" href="#indicators-—-admin-ui-codelists-dsds-projects" aria-label="Permalink to &quot;Indicators — Admin UI (codelists, DSDs, projects)&quot;">​</a></h1><p>This page covers the administrator screens for <strong>codelists</strong>, <strong>data structure definitions (DSDs)</strong>, and <strong>indicator projects</strong>.</p><p>Also see:</p><ul><li><a href="./indicators.html">Publishing indicators</a> — metadata schemas and API examples</li><li><a href="./indicators-frontend.html">Catalog frontend</a> — what users see on a published series page</li></ul><p>Indicators are summary measures derived from observed facts. When repeated over time at a regular frequency, they form a time series. NADA supports publishing indicators with rich metadata, interactive charts, data downloads, and API access.</p><p>The workflow for publishing indicators involves three building blocks — <strong>Codelists</strong>, <strong>Data Structure Definitions (DSDs)</strong>, and <strong>Indicator projects</strong> — before users can explore the data on the frontend.</p><hr><h2 id="codelists" tabindex="-1">Codelists <a class="header-anchor" href="#codelists" aria-label="Permalink to &quot;Codelists&quot;">​</a></h2><p>A codelist is a controlled vocabulary — a named list of codes and their labels — used to classify indicator data. For example, a codelist might define the set of valid country codes, or a list of indicator categories. Codelists are referenced by DSDs to define the allowed values for dimension columns.</p><h3 id="viewing-codelists" tabindex="-1">Viewing codelists <a class="header-anchor" href="#viewing-codelists" aria-label="Permalink to &quot;Viewing codelists&quot;">​</a></h3><p>Navigate to <strong>Settings → Codelists</strong> in the admin menu to see all available codelists.</p><p><img src="'+s+'" alt=""></p><p>The list shows the codelist ID, Name, Agency, latest version, and IDNO. Use the search bar or Status filter to narrow results. Click <strong>Add codelist</strong> to create a new one.</p><h3 id="codelist-details" tabindex="-1">Codelist details <a class="header-anchor" href="#codelist-details" aria-label="Permalink to &quot;Codelist details&quot;">​</a></h3><p>Click on any codelist name to open it. The <strong>Codelist details</strong> tab contains the identity fields: Name, Agency, Version, Status, and an auto-generated IDNO.</p><p><img src="'+n+'" alt=""></p><h3 id="codelist-items" tabindex="-1">Codelist items <a class="header-anchor" href="#codelist-items" aria-label="Permalink to &quot;Codelist items&quot;">​</a></h3><p>Click the <strong>Codelist items</strong> tab to view and manage the individual codes. Each item has a Code, Title, Sort order, and optional Translations. Use <strong>+ Add item</strong> to add codes manually, or use the search box to filter existing ones.</p><p><img src="'+r+'" alt=""></p><hr><h2 id="data-structure-definitions-dsds" tabindex="-1">Data Structure Definitions (DSDs) <a class="header-anchor" href="#data-structure-definitions-dsds" aria-label="Permalink to &quot;Data Structure Definitions (DSDs)&quot;">​</a></h2><p>A Data Structure Definition describes the structure of a dataset — which columns exist, what role each plays (dimension, attribute, observation value), and which codelist (if any) constrains the allowed values. DSDs are created once and reused across indicator projects.</p><h3 id="viewing-dsds" tabindex="-1">Viewing DSDs <a class="header-anchor" href="#viewing-dsds" aria-label="Permalink to &quot;Viewing DSDs&quot;">​</a></h3><p>Navigate to <strong>Settings → Data structures</strong> to see all available DSDs.</p><p><img src="'+d+'" alt=""></p><p>The list shows the Title, Name, Agency, version history, and the number of projects using each DSD. You can import DSDs from <strong>SDMX XML</strong> or <strong>JSON</strong> format, or create one manually using <strong>Add data structure</strong>.</p><h3 id="dsd-detail" tabindex="-1">DSD detail <a class="header-anchor" href="#dsd-detail" aria-label="Permalink to &quot;DSD detail&quot;">​</a></h3><p>Click on a DSD to open it. The left sidebar lists all <strong>Components</strong> (columns). The right panel shows the identity fields: Name, Agency, Version, IDNO, Title, Status, Description, and Notes.</p><p><img src="'+c+'" alt=""></p><p>Click <strong>Validate</strong> to check the DSD is structurally correct. Use <strong>Export JSON</strong> to download the DSD definition.</p><h3 id="dsd-components" tabindex="-1">DSD components <a class="header-anchor" href="#dsd-components" aria-label="Permalink to &quot;DSD components&quot;">​</a></h3><p>Click any component in the left sidebar to view and edit its properties: Name, Label, Column type (e.g. geography, time_period, observation_value), Data type, and the linked Codelist. The codelist codes are previewed inline.</p><p><img src="'+l+'" alt=""></p><p>Use <strong>+ Add</strong> in the components panel to add a new column to the DSD.</p><hr><h2 id="creating-an-indicator-project" tabindex="-1">Creating an indicator project <a class="header-anchor" href="#creating-an-indicator-project" aria-label="Permalink to &quot;Creating an indicator project&quot;">​</a></h2><p>An indicator project (Time series entry) ties together the metadata, data structure, and uploaded data for a single indicator series.</p><h3 id="overview-tab" tabindex="-1">Overview tab <a class="header-anchor" href="#overview-tab" aria-label="Permalink to &quot;Overview tab&quot;">​</a></h3><p>Navigate to <strong>Catalog</strong> in the admin menu and open an existing time series entry, or create a new one via <strong>Add study → Time series</strong>. The Overview tab shows the key settings: IDNO, title, date range, countries covered, data access policy, and the linked indicator database.</p><p><img src="'+h+'" alt=""></p><p>Set the <strong>Status</strong> to <em>Published</em> using the button in the right panel when ready to make the entry visible in the catalog.</p><h3 id="metadata-tab" tabindex="-1">Metadata tab <a class="header-anchor" href="#metadata-tab" aria-label="Permalink to &quot;Metadata tab&quot;">​</a></h3><p>The <strong>Metadata</strong> tab contains the full timeseries schema, organized into collapsible sections:</p><ul><li><strong>Series Description</strong> — IDNO, series name, database link, aliases, alternate identifiers, measurement unit, periodicity, base period, definitions, methodology, sources, topics, geographic units, and more.</li><li><strong>Metadata creation</strong> — provenance of the metadata record itself.</li><li><strong>Tags</strong> — free-text tags for discoverability.</li></ul><p><img src="'+p+'" alt=""></p><p>Click <strong>Save</strong> after making changes. Use <strong>Import</strong> to load metadata from a JSON file.</p><hr><h2 id="uploading-indicator-data" tabindex="-1">Uploading indicator data <a class="header-anchor" href="#uploading-indicator-data" aria-label="Permalink to &quot;Uploading indicator data&quot;">​</a></h2><p>Once the metadata is in place, upload the actual data through the <strong>Indicator data</strong> tab.</p><h3 id="attaching-a-data-structure" tabindex="-1">Attaching a data structure <a class="header-anchor" href="#attaching-a-data-structure" aria-label="Permalink to &quot;Attaching a data structure&quot;">​</a></h3><p>Before uploading data, attach a DSD by selecting it from the <strong>Data structure</strong> dropdown. The DSD defines the expected columns and their types. Use <strong>Download template</strong> to get a blank CSV with the correct column headers.</p><h3 id="uploading-a-csv-file" tabindex="-1">Uploading a CSV file <a class="header-anchor" href="#uploading-a-csv-file" aria-label="Permalink to &quot;Uploading a CSV file&quot;">​</a></h3><p>Click <strong>Upload</strong> and select a CSV file. The file must contain columns matching the DSD component names. Non-DSD columns are accepted but ignored during structured queries.</p><p>After upload, the data is displayed in the <strong>Data preview</strong> table, showing columns such as DATASET, INDICATOR, INDICATOR_NAME, COUNTRY_CODE, FREQ, TIME_PERIOD, and OBS_VALUE.</p><p><img src="'+g+'" alt=""></p><p>Use the <strong>Dimension summaries</strong> sub-tab to verify the range and distribution of values. Use <strong>Export CSV</strong> to download the currently loaded data, or <strong>Remove structure &amp; data</strong> to start over.</p>',56)])])}const y=e(m,[["render",u]]);export{w as __pageData,y as default};
